-- Material catalog and combat consumable seeds.
-- Public Data API access is deliberately disabled; all reads and writes go
-- through Clerk-authenticated server routes and the application ORM.
CREATE TABLE IF NOT EXISTS public.material (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "name" text NOT NULL UNIQUE,
 "type" text NOT NULL CHECK ("type" IN ('WOOD','METAL','MINERAL','LIQUID','PLANT','BONE','SKIN','CLOTH')),
 "description" text,
 "weightPerUnitKg" double precision,
 "hardness" integer NOT NULL DEFAULT 0 CHECK ("hardness" BETWEEN 0 AND 100),
 "physicalResistance" integer NOT NULL DEFAULT 0 CHECK ("physicalResistance" BETWEEN 0 AND 100),
 "magicResistance" integer NOT NULL DEFAULT 0 CHECK ("magicResistance" BETWEEN 0 AND 100),
 "attackGrant" integer NOT NULL DEFAULT 0,
 "defenseGrant" integer NOT NULL DEFAULT 0,
 "specialEffect" text,
 "naturalForm" text,
 "minimumForm" text,
 "rawForm" text,
 "marketForm" text,
 "fireReaction" text,
 "lightningReaction" text,
 "iceReaction" text,
 "active" boolean NOT NULL DEFAULT true,
 "createdAt" timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT material_name_not_blank CHECK (length(btrim(name)) BETWEEN 1 AND 100),
 CONSTRAINT material_weight_positive CHECK ("weightPerUnitKg" IS NULL OR ("weightPerUnitKg" > 0 AND "weightPerUnitKg" <= 100000))
);
ALTER TABLE public.material ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.material FROM PUBLIC, anon, authenticated;
REVOKE ALL ON SEQUENCE public.material_id_seq FROM PUBLIC, anon, authenticated;
-- Optional reference: NULL intentionally represents "Sin definir" on all old/new items.
ALTER TABLE public.item ADD COLUMN IF NOT EXISTS "materialId" integer REFERENCES public.material("id") ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS item_material_id_idx ON public.item ("materialId");
-- Item-instance durability is groundwork for the next wear-and-repair increment.
-- It does not change combat damage, item strength, or equipment rules yet.
ALTER TABLE public."characterItem" ADD COLUMN IF NOT EXISTS "durability" integer NOT NULL DEFAULT 100
 CHECK ("durability" BETWEEN 0 AND 100);
