-- New consumables are sold by the existing general store, independently of
-- business promotions. Never overwrite a custom item with the same name.
INSERT INTO public.item ("name","description","itemType","itemSubtype","acquisitionType","price","effects","allowedSlots")
SELECT 'Poción de salud (10 HP)','Restaura hasta 10 HP en combate. Un uso.', 'CONSUMABLE','Poción','PURCHASABLE',1200,
 '[{"type":"system_action","stat":"HP","action":"HEAL_HP","value":10,"description":"Restaura 10 HP, sin sobrepasar el máximo."}]'::jsonb, '[]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.item WHERE "name"='Poción de salud (10 HP)');
